import * as THREE from 'three/webgpu'
import * as TSL from 'three/tsl'
import { ssr } from 'three/examples/jsm/tsl/display/SSRNode'
import { bloom } from 'three/examples/jsm/tsl/display/BloomNode'
import { traa } from 'three/examples/jsm/tsl/display/TRAANode'
import { ssgi } from './effects/SSGINode'

import { useEffect, useRef, useState } from 'react'
import { Canvas, extend, useFrame, useThree } from '@react-three/fiber'
import { Environment, Lightformer } from '@react-three/drei'

const startBackground = new THREE.Color('#9bbfba')
const endBackground = new THREE.Color('#cfe7df')
const currentBackground = new THREE.Color()
const moleculeTarget = new THREE.Vector3()

const clamp = (value, min = 0, max = 1) => Math.min(Math.max(value, min), max)
const smooth = (start, end, value) => {
  const normalized = clamp((value - start) / (end - start))
  return normalized * normalized * (3 - 2 * normalized)
}

export default function App() {
  const [progress, setProgress] = useState(0)

  useEffect(() => {
    const update = () => {
      const scrollable = document.documentElement.scrollHeight - window.innerHeight
      setProgress(scrollable > 0 ? clamp(window.scrollY / scrollable) : 0)
    }

    update()
    window.addEventListener('scroll', update, { passive: true })
    window.addEventListener('resize', update)
    return () => {
      window.removeEventListener('scroll', update)
      window.removeEventListener('resize', update)
    }
  }, [])

  return (
    <main className="experience-shell">
      <div className="canvas-stage">
        <Canvas
          dpr={[1, 1.5]}
          gl={(props) => {
            extend(THREE)
            const renderer = new THREE.WebGPURenderer({ ...props, antialias: false })
            return renderer.init().then(() => renderer)
          }}
          camera={{ position: [0, 0, 12], fov: 32 }}>
          <color attach="background" args={[startBackground]} />
          <ambientLight intensity={1.5} color="#d4fff0" />
          <HeroMolecule progress={progress} />
          <Nanoport progress={progress} />
          <Environment>
            <group rotation={[-Math.PI / 3, 0, 1]}>
              <Lightformer form="circle" intensity={10} color="#d7fff1" rotation-x={Math.PI / 2} position={[0, 5, -9]} scale={2} />
              <Lightformer form="circle" intensity={2} color="#88d9d3" rotation-y={-Math.PI / 2} position={[10, 1, 0]} scale={8} />
              <Lightformer form="ring" color="#5bb7bb" intensity={8} onUpdate={(self) => self.lookAt(0, 0, 0)} position={[4, 5, 2]} scale={5} />
            </group>
          </Environment>
          <Effects />
        </Canvas>

        <div className="brand-reveal" style={{ opacity: smooth(0.76, 0.92, progress) }}>
          <div className="brand-name">AAGAMI<span>SE<span className="brand-q">Q<i /></span></span></div>
        </div>
      </div>
      <div className="scroll-space" />
    </main>
  )
}

function HeroMolecule({ progress }) {
  const molecule = useRef()
  const material = useRef()

  useFrame((state, delta) => {
    if (!molecule.current || !material.current) return

    const time = state.clock.elapsedTime
    const focus = smooth(0.08, 0.36, progress)
    const transit = smooth(0.39, 0.7, progress)
    const resolve = smooth(0.72, 0.9, progress)

    if (progress < 0.4) {
      moleculeTarget.set(
        1.8 * (1 - focus) + Math.sin(time * 0.45) * 0.08,
        0.35 * (1 - focus) + Math.cos(time * 0.6) * 0.06,
        0.6 + Math.sin(time * 0.35) * 0.08,
      )
    } else if (progress < 0.75) {
      moleculeTarget.set(0, 0, THREE.MathUtils.lerp(2.2, -2.2, transit))
    } else {
      moleculeTarget.set(-0.72, 0, -0.35)
    }

    molecule.current.position.lerp(moleculeTarget, 1 - Math.exp(-delta * 8))
    molecule.current.rotation.x += delta * 0.4
    molecule.current.rotation.y += delta * 0.7
    molecule.current.scale.setScalar(0.64 + focus * 0.38 - transit * 0.12)
    material.current.opacity = 1 - resolve
    material.current.emissiveIntensity = 0.45 + focus * 0.65 + transit * 0.35
  })

  return (
    <mesh ref={molecule} castShadow>
      <sphereGeometry args={[0.34, 64, 64]} />
      <meshPhysicalMaterial
        ref={material}
        color="#238c86"
        emissive="#34c5b0"
        metalness={0.42}
        roughness={0.16}
        clearcoat={1}
        clearcoatRoughness={0.12}
        transparent
      />
    </mesh>
  )
}

function Nanoport({ progress }) {
  const port = useRef()
  const membrane = useRef()
  const rim = useRef()
  const halo = useRef()

  useFrame((state, delta) => {
    if (!port.current || !membrane.current || !rim.current || !halo.current) return

    const visible = smooth(0.28, 0.42, progress) * (1 - smooth(0.7, 0.84, progress))
    const pulse = 1 + Math.sin(state.clock.elapsedTime * 1.7) * 0.025
    port.current.scale.lerp(new THREE.Vector3(pulse, pulse, pulse), 1 - Math.exp(-delta * 5))
    membrane.current.opacity = visible * 0.78
    rim.current.opacity = visible * 0.92
    halo.current.opacity = visible * 0.22
    port.current.visible = visible > 0.005
  })

  return (
    <group ref={port}>
      <mesh>
        <ringGeometry args={[1.18, 2.65, 128]} />
        <meshBasicMaterial ref={membrane} color="#3e7777" transparent side={THREE.DoubleSide} />
      </mesh>
      <mesh>
        <torusGeometry args={[1.18, 0.075, 20, 160]} />
        <meshPhysicalMaterial ref={rim} color="#60d7c4" emissive="#38a99d" emissiveIntensity={2.4} metalness={0.3} roughness={0.2} transparent />
      </mesh>
      <mesh>
        <torusGeometry args={[1.58, 0.018, 12, 160]} />
        <meshBasicMaterial ref={halo} color="#4bc9c2" transparent />
      </mesh>
    </group>
  )
}

function Effects() {
  const { gl, scene, camera } = useThree()
  const [postProcessing] = useState(() => new THREE.PostProcessing(gl))

  useEffect(() => {
    const scenePass = TSL.pass(scene, camera, { minFilter: THREE.NearestFilter, magFilter: THREE.NearestFilter })
    scenePass.setMRT(TSL.mrt({ output: TSL.output, normal: TSL.directionToColor(TSL.normalView), velocity: TSL.velocity }))
    const sceneColor = scenePass.getTextureNode('output')
    const sceneDepth = scenePass.getTextureNode('depth')
    const sceneNormal = TSL.sample((uv) => TSL.colorToDirection(scenePass.getTextureNode('normal').sample(uv)))
    const ssrPass = ssr(sceneColor, sceneDepth, sceneNormal)
    ssrPass.maxDistance.value = 4
    ssrPass.blurQuality.value = 1
    ssrPass.thickness.value = 0.12
    const bloomPass = bloom(sceneColor, 0.08, 0.7, 0.8)
    const ssgiPass = ssgi(sceneColor, sceneDepth, sceneNormal, camera)
    ssgiPass.sliceCount.value = 2
    ssgiPass.stepCount.value = 6
    ssgiPass.radius.value = 12
    ssgiPass.giIntensity.value = 18
    ssgiPass.aoIntensity.value = 1.4
    ssgiPass.thickness.value = 0.35
    const finalColor = TSL.vec4(sceneColor.rgb.mul(ssgiPass.a).add(sceneColor.rgb.mul(ssgiPass.rgb)), sceneColor.a)
    const compositePass = TSL.blendColor(finalColor.add(bloomPass), ssrPass)
    postProcessing.outputNode = traa(compositePass, sceneDepth, scenePass.getTextureNode('velocity'), camera)
    postProcessing.needsUpdate = true
  }, [camera, gl, postProcessing, scene])

  useFrame(() => postProcessing.render(), 1)
  return null
}
